<?php require_once __DIR__.'/config/security.php'; require_permission('assets.manage'); $page_title='Asset Maintenance'; $rows=$pdo->query("SELECT m.*,a.asset_tag,a.asset_name,u.name technician FROM maintenance_records m JOIN assets a ON a.id=m.asset_id LEFT JOIN users u ON u.id=m.technician_id ORDER BY m.maintenance_date DESC")->fetchAll(); $assets=$pdo->query('SELECT id,asset_tag,asset_name FROM assets ORDER BY asset_tag')->fetchAll(); include __DIR__.'/partials/header.php'; ?>
<div class="hero compact"><div><div class="eyebrow">MAINTENANCE</div><h1>Asset maintenance history</h1><p>Track preventive maintenance, repairs, cost and next due dates.</p></div></div>
<div class="panel"><form id="maintForm" class="settings-form"><div class="form-grid no-pad"><label>Asset<select name="asset_id" required><?php foreach($assets as $a):?><option value="<?=$a['id']?>"><?=e($a['asset_tag'].' — '.$a['asset_name'])?></option><?php endforeach;?></select></label><label>Maintenance Type<input name="maintenance_type" value="Preventive Maintenance" required></label><label>Date<input type="date" name="maintenance_date" value="<?=date('Y-m-d')?>" required></label><label>Next Due<input type="date" name="next_due"></label><label>Cost<input type="number" step="0.01" name="cost" value="0"></label></div><label>Description<textarea name="description"></textarea></label><button class="btn primary">Record Maintenance</button></form></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Type</th><th>Date</th><th>Next Due</th><th>Cost</th><th>Technician</th><th>Description</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['asset_tag'].' — '.$r['asset_name'])?></td><td><?=e($r['maintenance_type'])?></td><td><?=e($r['maintenance_date'])?></td><td><?=e($r['next_due']??'—')?></td><td>₱<?=number_format((float)$r['cost'],2)?></td><td><?=e($r['technician']??'—')?></td><td><?=e($r['description']??'')?></td></tr><?php endforeach;?></tbody></table></div></div>
<script>document.querySelector('#maintForm').addEventListener('submit',async e=>{e.preventDefault();let r=await fetch('api/maintenance.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});let j=await r.json();alert(j.message||'Saved');if(j.ok)location.reload()})</script><?php include __DIR__.'/partials/footer.php'; ?>
